import hashlib
import json
import os

BASELINE_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "baseline_frozen.yaml")
OUT_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "params.json")


